VALUES
(7001, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Chanclas Havaianas Top Brasil Unisex Originales', 'chanclas-havaianas-top-brasil-unisex-originales-7001', 'Chanclas Havaianas clásicas elaboradas en 100% caucho de alta resistencia. Suela antideslizante y tiras confortables para playa y uso diario. Garantía oficial de fábrica.', 65000, NULL, 8, 'SEED-PROD-7001', 'Havaianas', 'NUEVO', TRUE, FALSE, 4.6, 9, 1, NOW() - INTERVAL '27 days', NOW() - INTERVAL '27 days'),
(7002, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Sandalias Havaianas Slim Elegance Mujer', 'sandalias-havaianas-slim-elegance-mujer-7002', 'Sandalias brasileñas con tiras finas elegantes y acabado metalizado brillante. Máximo confort y ligereza para climas cálidos y outfits frescos en Cartagena.', 75000, 56250, 47, 'SEED-PROD-7002', 'Havaianas', 'NUEVO', TRUE, FALSE, 4.8, 2, 0, NOW() - INTERVAL '36 days', NOW() - INTERVAL '36 days'),
(7003, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Tenis Urbanos Nike Air Force 1 07 Low Cuero Blanco', 'tenis-urbanos-nike-air-force-1-07-low-cuero-blanco-7003', 'El ícono clásico del baloncesto llevado al streetwear urbano. Cuero prémium fácil de limpiar, costuras reforzadas y amortiguación Nike Air para confort todo el día.', 520000, NULL, 41, 'SEED-PROD-7003', 'Nike', 'NUEVO', TRUE, FALSE, 4.9, 13, 0, NOW() - INTERVAL '33 days', NOW() - INTERVAL '33 days'),
(7004, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Zapatillas de Running Adidas Ultraboost Light', 'zapatillas-de-running-adidas-ultraboost-light-7004', 'Nuestra tecnología Boost más ligera hasta la fecha para un retorno de energía sin precedentes. Exterior tejido Primeknit+ que abraza el pie con soporte focalizado.', 680000, NULL, 33, 'SEED-PROD-7004', 'Adidas', 'NUEVO', TRUE, FALSE, 4.7, 20, 2, NOW() - INTERVAL '16 days', NOW() - INTERVAL '16 days'),
(7005, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Nike Air Jordan 1 Red And Black', 'nike-air-jordan-1-red-and-black-7005', 'The Nike Air Jordan 1 in Red and Black is an iconic basketball sneaker known for its stylish design and high-performance features, making it a favorite among sneaker enthusiasts and athletes. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 592000, 532800, 37, 'SEED-PROD-7005', 'Nike', 'NUEVO', TRUE, FALSE, 4.6, 6, 2, NOW() - INTERVAL '24 days', NOW() - INTERVAL '24 days'),
(7006, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Nike Baseball Cleats', 'nike-baseball-cleats-7006', 'Nike Baseball Cleats are designed for maximum traction and performance on the baseball field. They provide stability and support for players during games and practices. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 316000, NULL, 8, 'SEED-PROD-7006', 'Nike', 'NUEVO', TRUE, FALSE, 4.6, 7, 3, NOW() - INTERVAL '23 days', NOW() - INTERVAL '23 days'),
(7007, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Puma Future Rider Trainers', 'puma-future-rider-trainers-7007', 'The Puma Future Rider Trainers offer a blend of retro style and modern comfort. Perfect for casual wear, these trainers provide a fashionable and comfortable option for everyday use. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 355000, NULL, 20, 'SEED-PROD-7007', 'Puma', 'NUEVO', TRUE, FALSE, 4.8, 6, 1, NOW() - INTERVAL '4 days', NOW() - INTERVAL '4 days'),
