(7009, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Sports Sneakers Off White Red', 'sports-sneakers-off-white-red-7009', 'Another variant of the Sports Sneakers in Off White Red, featuring a unique design. These sneakers offer style and comfort for casual occasions. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 434000, NULL, 15, 'SEED-PROD-7009', 'Off White', 'NUEVO', TRUE, FALSE, 4.6, 13, 2, NOW() - INTERVAL '6 days', NOW() - INTERVAL '6 days'),
(7010, 6001, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%calzado%' OR LOWER(nombre) LIKE '%zapato%' ORDER BY id DESC LIMIT 1), (SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Black & Brown Slipper - Comfort Trends', 'black-brown-slipper-comfort-trends-7010', 'The Black & Brown Slipper is a comfortable and stylish choice for casual wear. Featuring a blend of black and brown colors, it adds a touch of sophistication to your relaxation. Garantía directa de 12 meses. Producto 100% original con despacho asegurado en Cartagena de Indias.', 79000, NULL, 33, 'SEED-PROD-7010', 'Comfort Trends', 'NUEVO', TRUE, FALSE, 4.9, 14, 3, NOW() - INTERVAL '13 days', NOW() - INTERVAL '13 days'),
